import{_ as t,a as s,b as o,c as n,d as i,e as a,f as r,g as l,h as u}from"./chunks/technic-light-runtime.BM1alCex.js";import{_ as d,o as c,c as p,a3 as m}from"./chunks/framework.BlfGB29P.js";const A=JSON.parse('{"title":"Technic","description":"Installez le jeu de widgets externe « Technic » et connectez « Window – Wall » à Home Assistant.","frontmatter":{"title":"Technic","description":"Installez le jeu de widgets externe « Technic » et connectez « Window – Wall » à Home Assistant."},"headers":[],"relativePath":"fr/projects/grafik-visual-studio/technic.md","filePath":"fr/projects/grafik-visual-studio/technic.md","lastUpdated":1793128957000}'),g={name:"fr/projects/grafik-visual-studio/technic.md"};function h(f,e,v,b,q,L){return c(),p("div",null,[...e[0]||(e[0]=[m('<h1 id="technic" tabindex="-1">Technic <a class="header-anchor" href="#technic" aria-label="Permalink to &quot;Technic {#technic}&quot;">​</a></h1><p>À partir de <strong>Studio 0.1.296</strong>, le thermostat propose en outre une fonction <a href="/fr/projects/grafik-visual-studio/ha-quellen-climate">Climate</a> (gestion du climat) — désactivée par défaut — incluant : deux consignes, modes de fonctionnement, préréglages, ventilation, oscillation, humidité et marche/arrêt, selon les capacités de l&#39;appareil. Les propriétés du widget et les messages d&#39;exécution sont disponibles en allemand, anglais et français ; les paramètres existants restent valides.</p><p>Les paquets et outils complémentaires sont proposés de manière centralisée sur <a href="https://visualstudio.ugso-software.de/?lang=de" target="_blank" rel="noreferrer">visualstudio.ugso-software.de</a>. Ce site open source contient des descriptions et des instructions ; le téléchargement s&#39;effectue via le catalogue de paquets.</p><p><strong>Inspiré des <a href="https://github.com/Sefina-DS/ioBroker.vis-2-widgets-technic" target="_blank" rel="noreferrer">widgets « Technic » pour ioBroker créés par Sefina-DS</a>.</strong> Adaptation spécifique pour Home Assistant.</p><p>À partir de <strong>Studio 0.1.203</strong>, vous pouvez installer <strong>Technic 1.6.0</strong>. Ce paquet contient les sept types de widgets : <strong>Window – Wall</strong>, <strong>Switch – Boolean</strong>, <strong>Dimmer – Light</strong>, <strong>Room – Overlay</strong>, <strong>Clock – Date</strong>, <strong>Thermostat – Temperature</strong> et <strong>Status – List</strong>. La version 1.6.0 peut être installée via le gestionnaire de paquets en tant qu&#39;extension des versions précédentes ; les widgets existants sont conservés.</p><h2 id="status-–-list" tabindex="-1">Status – List <a class="header-anchor" href="#status-–-list" aria-label="Permalink to &quot;Status – List {#status-–-list}&quot;">​</a></h2><p><img src="'+t+'" alt="Liste d&#39;états affichant la température et l&#39;état d&#39;une fenêtre ; données de test simulées pour HA"></p><p>La liste d&#39;états affiche jusqu&#39;à <strong>dix lignes d&#39;état en lecture seule</strong>. Par défaut, le nombre de lignes est réglé sur <strong>0</strong> ; le widget apparaît alors vide. Taille par défaut : <strong>160 × 120 pixels</strong>. Dans la section <strong>Lignes d&#39;état</strong>, vous pouvez configurer le nombre de lignes, le <strong>décalage de la colonne des valeurs (90 px)</strong> et la <strong>marge gauche du conteneur (8 px)</strong>. Le décalage détermine la largeur de la colonne des libellés ; la colonne des valeurs commence ensuite, avec un espacement de 4 px. L&#39;espacement gauche du conteneur s&#39;ajoute à la marge interne fixe de 8 px.</p><p>Selon le nombre défini, les <strong>lignes d&#39;état [1]</strong> à <strong>[10]</strong> s&#39;affichent. Chaque ligne se voit attribuer une étiquette et une entité Home Assistant. Le type <strong>Nombre</strong> prend en charge les unités, les décimales et la couleur des chiffres. Le type <strong>Vrai / Faux</strong> permet de définir des textes et des couleurs pour les états ON/OFF, ainsi que des entités supplémentaires (séparées par des virgules) combinées par des opérateurs <strong>ET</strong> ou <strong>OU</strong>. Les champs d&#39;origine <code>oid1</code> à <code>oid10</code> correspondent aux champs Studio <code>rowEntityId1</code> à <code>rowEntityId10</code> ; les champs <code>oidsExtra1</code> à <code>oidsExtra10</code> correspondent aux champs <code>extraEntityIds1</code> à <code>extraEntityIds10</code>.</p><p>Les valeurs manquantes, inconnues ou indisponibles sont traitées comme <code>—</code>. La taille de la police, la police elle-même, le style gras et la couleur de l&#39;étiquette sont définis via <strong>CSS → Police et texte</strong>. Les étiquettes ou valeurs trop longues sont tronquées avec des points de suspension ; le texte complet est alors visible dans une info-bulle (tooltip). Si vous utilisez des unités longues, augmentez la largeur du widget ; l&#39;exemple illustré utilise 240 pixels. Si le nombre de lignes est trop élevé, un défilement (scroll) est activé au sein du widget. Les clics ne modifient pas les états dans Home Assistant et ne masquent pas les étiquettes. Toutes les lignes et tous les espacements sont conservés lors de l&#39;exportation du projet ou du widget.</p><h2 id="thermostat-–-temperature" tabindex="-1">Thermostat – Température <a class="header-anchor" href="#thermostat-–-temperature" aria-label="Permalink to &quot;Thermostat – Température {#thermostat-–-temperature}&quot;">​</a></h2><p><img src="'+s+'" alt="Contrôleur de température après une modification de la consigne ; l&#39;étiquette reste visible"></p><p>Le régulateur de température affiche la température de consigne/réelle, l&#39;humidité, l&#39;état du servomoteur et le mode refroidissement. Taille standard : <strong>220 × 220 pixels</strong>, plage <strong>15–28</strong>, pas de <strong>0,5</strong>. Dans la section <strong>Général</strong>, vous pouvez configurer le libellé, l&#39;affichage, la position (haut/bas), la taille de l&#39;icône et la protection en écriture. Dans la section <strong>Régulateur</strong>, vous définissez les limites et le pas ; la section <strong>Couleurs</strong> permet de configurer les états MARCHE, ARRÊT et Refroidissement.</p><table tabindex="0"><thead><tr><th>Champ d&#39;origine</th><th>Liaison Studio</th><th>Home Assistant</th></tr></thead><tbody><tr><td><code>oid_temp_soll</code></td><td>Température de consigne</td><td><code>climate</code> (avec consigne unique) ou <code>input_number</code></td></tr><tr><td><code>oid_temp_ist</code></td><td>Température réelle</td><td>Capteur de température ou <code>climate.current_temperature</code></td></tr><tr><td><code>oid_feuchtigkeit</code></td><td>Humidité</td><td>Capteur (en pourcentage) ou <code>climate.current_humidity</code></td></tr><tr><td><code>oid_stellmotor</code></td><td>Servomoteur</td><td>Capteur 0–100 %, état booléen ou <code>climate.hvac_action</code></td></tr><tr><td><code>oid_kuehlmodus</code></td><td>Mode refroidissement</td><td>État booléen ou état de refroidissement d&#39;une entité <code>climate</code></td></tr></tbody></table><p>Les liaisons de lecture laissées vides utilisent les attributs correspondants de l&#39;entité de consigne <code>climate</code>. Avec l&#39;<code>input_number</code>, des capteurs distincts sont nécessaires. Une activité de chauffage/refroidissement correspond à <strong>100 %</strong>, tandis qu&#39;un état inactif/éteint correspond à <strong>0 %</strong> ; il ne s&#39;agit pas ici de la position mesurée de la vanne. Les valeurs manquantes ou indisponibles sont traitées via l&#39;<code>—</code>.</p><p>En mode exécution (runtime), vous pouvez manipuler l&#39;<strong>arc à 300°</strong> ou utiliser le curseur via le clavier. L&#39;écriture (<code>climate.set_temperature</code> ou <code>input_number.set_value</code>) ne s&#39;effectue qu&#39;au moment du relâchement. Le système vérifie au préalable les capacités et limites actuelles de Home Assistant (HA), ainsi que les pas d&#39;incrémentation. Toute incompatibilité de grille, état inconnu, protection en écriture ou mode édition empêche l&#39;opération d&#39;écriture. Le curseur modifie uniquement la valeur de consigne ; le mode de fonctionnement et l&#39;état marche/arrêt ne sont pas affectés. En cas d&#39;erreur liée à Home Assistant, un message s&#39;affiche ; les libellés restent visibles.</p><p><img src="'+o+'" alt="Historique sur sept jours avec températures de consigne et réelle, ainsi qu&#39;un axe séparé pour le servomoteur ; données de test simulées"></p><p>La fonction <strong>Historique</strong> affiche les données sur <strong>24 heures</strong> ou <strong>7 jours</strong> en puisant dans l&#39;<strong>enregistreur (Recorder) de Home Assistant</strong>. Les températures de consigne et réelle utilisent l&#39;axe des températures, tandis que le servomoteur utilise l&#39;axe des pourcentages situé à droite. Les trois couleurs sont configurables dans la section <strong>Historique (HA-Recorder)</strong>. Les valeurs inconnues entraînent une interruption de la courbe. L&#39;enregistreur doit capturer les entités sélectionnées et conserver les données pour la période souhaitée. Ici, le paramètre ioBroker <code>influxInstance</code> est remplacé par les données issues de l&#39;enregistreur Home Assistant. Toutes les liaisons, options d&#39;affichage et couleurs sont préservées lors de l&#39;exportation du projet ou du widget. Les illustrations sont issues d&#39;un test local utilisant des réponses simulées de Home Assistant.</p><h2 id="clock-–-date" tabindex="-1">Horloge – Date <a class="header-anchor" href="#clock-–-date" aria-label="Permalink to &quot;Horloge – Date {#clock-–-date}&quot;">​</a></h2><p><img src="'+n+'" alt="Horloge en temps réel avec affichage des secondes et date en allemand"></p><p>L&#39;horloge affiche l&#39;<strong>heure locale et le fuseau horaire du navigateur</strong>. Elle ne nécessite aucune entité HA (Home Assistant). L&#39;affichage se met à jour chaque seconde sans redessiner les autres widgets ; si l&#39;onglet du navigateur a été mis en pause, l&#39;heure actuelle est réactualisée lors de sa réactivation.</p><p>Dans la section <strong>Général</strong>, vous pouvez définir la disposition (côte à côte ou l&#39;un en dessous de l&#39;autre), l&#39;alignement (gauche, centre ou droite), l&#39;espacement, un arrière-plan optionnel, le rayon des coins et la marge intérieure. La taille par défaut est de 260 × 90 pixels. Les dates longues ou les polices de grande taille nécessitent davantage d&#39;espace ; le contenu qui dépasse reste accessible via une barre de défilement.</p><p>Dans la section <strong>Heure</strong>, vous pouvez configurer l&#39;affichage, le format 12/24 heures, les secondes, la couleur, la taille de la police et le style en gras. Le format 12 heures utilise les mentions AM/PM. Dans la section <strong>Date</strong>, vous pouvez configurer séparément l&#39;affichage, la couleur, la taille de la police et le style en gras.</p><p>La langue utilisée pour la date est indépendante de la langue de l&#39;interface Studio : allemand, anglais, français, espagnol, italien ou néerlandais. Différents formats sont disponibles : jour-mois-année, mois-jour-année ou année-mois-jour ; les séparateurs peuvent être des points, des tirets, des barres obliques ou des espaces. Le mois peut être affiché sous forme numérique, abrégée ou complète ; l&#39;année peut être indiquée sur deux ou quatre chiffres, et un zéro peut être ajouté devant le jour si nécessaire. Le jour de la semaine peut être masqué, affiché en format abrégé ou complet. Les noms des mois et des jours sont issus des paramètres linguistiques du navigateur. Toutes ces options sont conservées lors de l&#39;exportation du projet ou du widget.</p><h2 id="room-–-overlay" tabindex="-1">Pièce – Superposition (Overlay) <a class="header-anchor" href="#room-–-overlay" aria-label="Permalink to &quot;Pièce – Superposition (Overlay) {#room-–-overlay}&quot;">​</a></h2><p><img src="'+i+'" alt="Tuile de pièce avec libellé visible et page de destination du studio ouverte"></p><p>La tuile de pièce affiche un <strong>nom de pièce</strong> personnalisable ainsi que jusqu&#39;à <strong>dix lignes d&#39;état</strong>. Il est possible de configurer la couleur du nom, la taille de la police, le style gras, l&#39;alignement horizontal et vertical, ainsi que les quatre marges internes. Taille par défaut : 160 × 100 pixels.</p><p>Dans la section <strong>Lignes d&#39;état</strong>, vous définissez le nombre de lignes, la taille de la police et la couleur du texte. Les lignes peuvent être disposées les unes en dessous des autres ou horizontalement, avec des séparateurs et des espacements. Les groupes correspondants, de <strong>Ligne d&#39;état [1]</strong> à <strong>[10]</strong>, s&#39;affichent en fonction du nombre choisi.</p><p>Chaque ligne se voit attribuer un libellé et une entité Home Assistant. Pour le type <strong>Nombre</strong>, il est possible de définir une unité, le nombre de décimales et la couleur du chiffre. Pour le type <strong>Vrai / Faux</strong>, vous pouvez configurer le texte et la couleur pour les états MARCHE/ARRÊT, ainsi qu&#39;ajouter des entités supplémentaires (séparées par des virgules) combinées par des opérateurs <strong>ET</strong> ou <strong>OU</strong>. Les valeurs manquantes, inconnues ou indisponibles s&#39;affichent sous la forme <code>—</code> ; elles ne sont pas considérées comme étant à l&#39;état « éteint ». Les données sont traitées en mode lecture seule.</p><p>Dans la section <strong>Comportement au clic / Popup</strong>, sélectionnez une <strong>page cible Studio</strong> existante. L&#39;option <strong>Popup</strong> ouvre l&#39;instance d&#39;exécution de cette page dans une fenêtre modale (dialogue), tandis que <strong>Changer de page</strong> permet d&#39;y accéder directement. Une vue ioBroker doit d&#39;abord être reproduite en tant que page Studio. Si aucune cible valide n&#39;est définie, la tuile ne déclenche aucune action ; les auto-références et les inclusions récursives sont interdites. Dans l&#39;éditeur, un clic permet de sélectionner l&#39;élément.</p><p>Il est possible de configurer la largeur et la hauteur de la fenêtre contextuelle (popup), sa position X/Y fixe (au lieu d&#39;un centrage automatique), ainsi que l&#39;arrière-plan, la couleur et l&#39;épaisseur de la bordure, et le rayon des coins. Vous pouvez également définir la fermeture au clic en dehors de la fenêtre, l&#39;affichage d&#39;un bouton de fermeture, et une fermeture automatique après un certain nombre de secondes (la valeur <code>0</code> désactive cette fonction). La touche <strong>Échap</strong> permet toujours de fermer la fenêtre. La popup reste ouverte lors des mises à jour en temps réel ; son libellé demeure visible. La fenêtre se ferme automatiquement lors d&#39;un changement de page ou de la suppression de la tuile. La taille est limitée aux dimensions de l&#39;écran. Tous les paramètres sont conservés lors de l&#39;exportation du projet ou du widget.</p><h2 id="installieren" tabindex="-1">Installation <a class="header-anchor" href="#installieren" aria-label="Permalink to &quot;Installation {#installieren}&quot;">​</a></h2><p>Téléchargez le fichier <a href="https://visualstudio.ugso-software.de/?kind=widget&amp;lang=de" target="_blank" rel="noreferrer">ugso.technic.wg</a>. Accédez à <strong>Paramètres → Packs de widgets → Installer un fichier .wg / .wg.zip local</strong> et sélectionnez le fichier. Après un rechargement, l&#39;ensemble apparaît, associé automatiquement à une couleur disponible. Ce composant est indépendant des widgets intégrés, ainsi que des modules liés à la météo et au chauffage.</p><p>Le <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/ha_grafik_visual_studio/packages/technic" target="_blank" rel="noreferrer">code source et la procédure de construction reproductible du paquet</a> sont accessibles au public. Le paquet téléchargeable contient les éléments <code>README.md</code> et <code>LICENSE.txt</code>, incluant le texte intégral de la licence MIT ainsi que la mention d&#39;origine <code>Copyright (c) 2026 Sefina-DS</code>.</p><h2 id="window-–-wall" tabindex="-1">Fenêtre – Mur <a class="header-anchor" href="#window-–-wall" aria-label="Permalink to &quot;Fenêtre – Mur {#window-–-wall}&quot;">​</a></h2><p>Dans la section <strong>Général</strong>, vous pouvez configurer le libellé, l&#39;option <strong>Afficher le libellé</strong>, la position (haut/bas), la taille de l&#39;icône (10–100 %), le côté de la poignée (gauche/droite) et la couleur de l&#39;icône. La taille par défaut est de 120 × 160 pixels. L&#39;option <strong>Lecture seule</strong> verrouille l&#39;utilisation.</p><p>Sous <strong>Points de données</strong>, vous trouverez trois liaisons HA (Home Assistant) indépendantes :</p><table tabindex="0"><thead><tr><th>Champ d&#39;origine</th><th>Champ Studio</th><th>Home Assistant</th></tr></thead><tbody><tr><td><code>oid_kontakt</code></td><td>Contact d&#39;ouverture : Entité</td><td>par ex. <code>binary_sensor.fenster_garage</code> ; <code>on</code> signifie « ouvert »</td></tr><tr><td><code>oid_rollo</code></td><td>Volet roulant : Entité « cover »</td><td>par ex. <code>cover.rollo_garage</code> ; lit <code>current_position</code></td></tr><tr><td><code>oid_modus</code></td><td>Mode : Entité</td><td>par ex. <code>input_boolean.rollo_manuell</code> ; désactivé = Automatique, activé = Manuel</td></tr></tbody></table><p>Chaque liaison dispose de sa propre option d&#39;inversion. <strong>Inverser le volet</strong> inverse l&#39;affichage ainsi que la valeur d&#39;écriture (<code>100 − Position</code>). En fonctionnement normal, 0 signifie « fermé » et 100 signifie « ouvert ». Une valeur inconnue reste inconnue, même après inversion. Le contact est uniquement lu. Un symbole <strong>A/M</strong> (optionnel) indique le mode ; <code>?</code> indique un mode inconnu.</p><p><img src="'+a+'" alt="Composant Technic installé et liaisons HA dans l&#39;éditeur"></p><h2 id="bedienung" tabindex="-1">Utilisation <a class="header-anchor" href="#bedienung" aria-label="Permalink to &quot;Utilisation {#bedienung}&quot;">​</a></h2><p>En mode exécution (Runtime), un clic sur la fenêtre ouvre une boîte de dialogue dotée d&#39;un curseur de position, de valeurs rapides (<strong>0 / 25 / 50 / 75 / 100 %</strong>) et d&#39;une option de changement de mode. L&#39;utilisation est également possible via le clavier ; la touche Échap ou le bouton <strong>Fermer</strong> permettent de quitter la boîte de dialogue. L&#39;action liée au volet roulant utilise exclusivement l&#39;entité <code>cover.set_cover_position</code>. La commande de position (<code>supported_features</code> avec SET_POSITION) est vérifiée avant toute écriture. Le changement de mode ne s&#39;applique qu&#39;aux entités <code>input_boolean</code> ou <code>switch</code> disponibles. Un capteur reste un simple élément d&#39;affichage.</p><p>L&#39;assistant de mode ne représente que l&#39;interrupteur : vous devez configurer l&#39;automatisation réelle des volets roulants dans Home Assistant. Aucune automatisation n&#39;est créée ou désactivée par ce biais. En cas d&#39;échec d&#39;une action, une notification s&#39;affiche et permet de retenter l&#39;opération ; les actions en attente ne sont pas envoyées en double.</p><p><img src="'+r+'" alt="Boîte de dialogue en mode exécution avec position du volet et changement de mode"></p><h2 id="switch-–-boolean" tabindex="-1">Interrupteur – Booléen <a class="header-anchor" href="#switch-–-boolean" aria-label="Permalink to &quot;Interrupteur – Booléen {#switch-–-boolean}&quot;">​</a></h2><p>L&#39;interrupteur reprend les options de configuration de <code>tplTechnicSchalterBoolean</code>. Paramètres par défaut : <strong>Device</strong> (appareil), libellé visible en bas, dimensions 120 × 160 pixels, icône d&#39;alimentation affichée à 80 %, couleur pour l&#39;état ACTIF (<code>#2dd4b0</code>) et couleur pour l&#39;état INACTIF (<code>#5f8f8a</code>).</p><p>Le <strong>point de données (MARCHE/ARRÊT)</strong> permet de lier l&#39;entité Home Assistant. <strong>Type de valeur → Vrai / Faux</strong> : lit les états <code>on</code>/<code>off</code> et permet de commuter les éléments <code>switch</code>, <code>light</code> ou <code>input_boolean</code> via <code>turn_on</code>/<code>turn_off</code>. <strong>0 / 1</strong> : lit exclusivement les valeurs 0 et 1 et écrit des valeurs numériques dans un élément auxiliaire <code>input_number</code>. Les limites et le pas de cet élément doivent être compatibles avec ces valeurs. Les capteurs conservent leur rôle d&#39;indicateurs ; les états inconnus, manquants ou non disponibles ne peuvent pas être commutés.</p><p><strong>Sélectionner une icône</strong> : propose 16 types de symboles : sélection, PC de bureau, alimentation, lampe de chevet, suspension, suspension ronde, lampe de bureau, spots, ruban LED RGB, lampe de table, lien, ventilateur, clé, smartphone, prise de courant et TV. Il s&#39;agit de dessins géométriques SVG originaux, et non de simples tracés graphiques importés. La couleur (pour les états MARCHE/ARRÊT) et la taille sont réglables. L&#39;option « Sélection » affiche une coche uniquement lorsque l&#39;état est MARCHE.</p><p>Un clic sur le symbole déclenche la commutation en mode exécution (runtime) ; l&#39;intitulé reste visible. L&#39;utilisation au clavier est possible via les touches Tab et Entrée/Espace. L&#39;option <strong>Lecture seule</strong> empêche toute modification. Les actions en cours ne sont pas envoyées en double ; en cas d&#39;erreur, un message s&#39;affiche et permet de réessayer. <strong>MARCHE (Aperçu)</strong> ne s&#39;applique que dans l&#39;éditeur, lorsque l&#39;élément n&#39;est pas lié. Tous les paramètres sont conservés dans le projet et lors de l&#39;exportation.</p><p><img src="'+l+'" alt="Commutateur après activation, avec intitulé visible"></p><h2 id="dimmer-–-light" tabindex="-1">Variateur – Éclairage <a class="header-anchor" href="#dimmer-–-light" aria-label="Permalink to &quot;Variateur – Éclairage {#dimmer-–-light}&quot;">​</a></h2><p>Correspond aux options de <code>tplTechnicReglerLicht</code> : libellé <strong>Light</strong> (Éclairage), affiché en bas ; taille de l&#39;icône : 80 %, dimensions : 160 × 200 pixels. <strong>Couleur (activé)</strong> correspond à <code>#2ecfbf</code>, <strong>Couleur (désactivé)</strong> à <code>#5f8f8a</code>, et <strong>Arrière-plan du curseur</strong> à <code>#0d1820</code>. La taille, les couleurs et la position du libellé sont configurables ; l&#39;affichage repose sur une implémentation SVG spécifique.</p><p>Le champ <strong>On/Off : Entité</strong> accepte <code>light</code>, <code>switch</code> ou <code>input_boolean</code>. Le champ <strong>Luminosité : Entité (0–100)</strong> accepte une entité dimmable (<code>light</code>) ou un « helper » (élément auxiliaire) de type numérique (<code>input_number</code>). Pour un éclairage HA (Home Assistant) standard, saisissez <strong>la même entité « light » dans les deux champs</strong>. Le système convertit l&#39;attribut HA <code>brightness</code> (plage 0–255) en pourcentage. Lorsque l&#39;éclairage est éteint, la valeur affichée est 0 %. L&#39;élément auxiliaire numérique doit être configuré avec : min = 0, max = 100 et pas (step) = 1. Les capteurs peuvent afficher des valeurs, mais ne permettent pas de contrôle.</p><p>L&#39;option <strong>Lier On/Off à la luminosité</strong> est activée par défaut : l&#39;état « activé » définit la luminosité à 100 %, l&#39;état « désactivé » à 0 %, et toute modification de la luminosité au-dessus de 0 allume l&#39;éclairage. Les deux entités liées doivent être disponibles et inscriptibles. Si la même entité « light » est utilisée, une seule commande HA est générée. Sans cette liaison, les entités restent indépendantes ; toutefois, une action sur la luminosité via <code>light.turn_on</code> entraînera tout de même l&#39;allumage de l&#39;éclairage concerné. 0 % utilisé <code>light.turn_off</code>.</p><p>Faites glisser l&#39;arc de cercle extérieur ou utilisez le curseur (via le clavier). La valeur s&#39;affiche localement pendant le déplacement et n&#39;est transmise qu&#39;au moment du relâchement. Le bouton central « Power » permet d&#39;allumer ou d&#39;éteindre (ON/OFF). L&#39;étiquette reste visible. L&#39;option <strong>Lecture seule</strong> bloque toute action ; les entités inconnues ou non dimmables ne peuvent pas être manipulées. Les valeurs en temps réel manquantes ne sont pas remplacées par des valeurs de prévisualisation. Les paramètres <strong>ON (Prévisualisation)</strong> et <strong>Luminosité (Prévisualisation)</strong> ne s&#39;appliquent que dans l&#39;éditeur, pour les éléments non liés.</p><p>L&#39;hôte vérifie toutes les cibles avant la première opération d&#39;écriture. Dans le cas d&#39;entités distinctes, les appels vers HA (Home Assistant) sont exécutés les uns après les autres ; une erreur côté fournisseur peut entraîner une application partielle de l&#39;action. Le message d&#39;erreur invite à vérifier l&#39;état actuel avant toute nouvelle tentative. Les actions en cours ne sont pas envoyées en double. Le fonctionnement a été validé avec des entités HA simulées ; le matériel réel doit faire l&#39;objet de tests distincts.</p><p><img src="'+u+'" alt="Contrôleur d&#39;éclairage en exécution (runtime) réglé à 50 % avec étiquette visible"></p><h2 id="vorschau-und-export" tabindex="-1">Prévisualisation et exportation <a class="header-anchor" href="#vorschau-und-export" aria-label="Permalink to &quot;Prévisualisation et exportation {#vorschau-und-export}&quot;">​</a></h2><p>La <strong>Prévisualisation</strong> propose des options pour l&#39;état des fenêtres, la position des volets roulants et le mode manuel. Ces valeurs ne s&#39;appliquent que dans l&#39;éditeur, pour les affichages non liés. En cas de liaison, ce sont les valeurs en temps réel qui sont lues. En mode exécution (runtime), les valeurs non liées ou manquantes restent inconnues ; elles ne sont pas remplacées par des valeurs de prévisualisation. Dans l&#39;éditeur, les clics ne déclenchent aucune action de commutation dans HA.</p><p>Toutes les options d&#39;affichage, les trois liaisons d&#39;entités, les inversions, les valeurs de prévisualisation et la protection en écriture sont conservées lors de l&#39;exportation du projet et du widget. Le test a été effectué avec des entités HA simulées ; une commande de volets roulants réelle doit être testée avec votre propre matériel.</p>',60)])])}const T=d(g,[["render",h]]);export{A as __pageData,T as default};
